import type { MultiLineString, MultiPolygon, Position } from "geojson";

/**
 * North American rivers and lakes for the atlas map (Natural Earth 1:50m,
 * public domain). The JSON is generated by `scripts/generate-hydrography.ts`
 * and loaded lazily after the country topology so the first paint never waits
 * on decorative water.
 */
export interface EncodedHydrography {
  source: string;
  encoding: "delta-hundredths";
  rivers: Array<{ n: string; r: number; l: number[][] }>;
  lakes: Array<{ n: string; r: number; p: number[][] }>;
}

export interface AtlasRiver {
  name: string;
  /** Natural Earth scalerank: 1 = continental trunk river, 6 = regional. */
  rank: number;
  geometry: MultiLineString;
}

export interface AtlasLake {
  name: string;
  geometry: MultiPolygon;
}

export interface AtlasHydrography {
  rivers: AtlasRiver[];
  lakes: AtlasLake[];
}

/** Decode `[lon0, lat0, dLon1, dLat1, …]` hundredths of a degree into positions. */
export function decodeHydroLine(encoded: readonly number[]): Position[] {
  const out: Position[] = [];
  let lon = 0;
  let lat = 0;
  for (let i = 0; i + 1 < encoded.length; i += 2) {
    lon += encoded[i]!;
    lat += encoded[i + 1]!;
    out.push([lon / 100, lat / 100]);
  }
  return out;
}

export function decodeHydrography(raw: EncodedHydrography): AtlasHydrography {
  if (raw.encoding !== "delta-hundredths") {
    throw new Error(`hydrography: unsupported encoding ${String(raw.encoding)}`);
  }
  return {
    rivers: raw.rivers.map(r => ({
      name: r.n,
      rank: r.r,
      geometry: { type: "MultiLineString", coordinates: r.l.map(decodeHydroLine) },
    })),
    lakes: raw.lakes.map(l => ({
      name: l.n,
      geometry: { type: "MultiPolygon", coordinates: [l.p.map(decodeHydroLine)] },
    })),
  };
}

let cached: AtlasHydrography | null = null;
let pending: Promise<AtlasHydrography> | null = null;

export function getCachedAtlasHydrography(): AtlasHydrography | null {
  return cached;
}

export function loadAtlasHydrography(): Promise<AtlasHydrography> {
  if (cached) return Promise.resolve(cached);
  if (pending) return pending;
  pending = import("../data/geo/na-hydrography.json")
    .then(mod => {
      const raw = ((mod as { default?: unknown }).default ?? mod) as EncodedHydrography;
      cached = decodeHydrography(raw);
      return cached;
    })
    .catch((err: unknown) => {
      pending = null;
      throw err;
    });
  return pending;
}

/** River stroke tiers: trunk rivers read at continent scale, tributaries only once zoomed. */
export type RiverTier = "trunk" | "major" | "regional";

export function riverTier(rank: number): RiverTier {
  if (rank <= 2) return "trunk";
  if (rank <= 4) return "major";
  return "regional";
}

/**
 * Opacity for a river tier at map zoom `k`. Regional rivers fade in between
 * k≈1.1 and 1.8 so the continent view stays calm.
 */
export function riverTierOpacity(tier: RiverTier, k: number): number {
  const ramp = (lo: number, hi: number) => Math.max(0, Math.min(1, (k - lo) / (hi - lo)));
  if (tier === "trunk") return 0.62 + 0.3 * ramp(0.6, 1.6);
  if (tier === "major") return 0.32 + 0.56 * ramp(0.7, 1.5);
  return 0.78 * ramp(1.1, 1.8);
}
